    </div>
    <div id="sb-search-bar">
      <div class="sb-si">
        <svg viewBox="0 0 24 24"><path d="M15.5 14h-.79l-.28-.27A6.471 6.471 0 0 0 16 9.5 6.5 6.5 0 1 0 9.5 16c1.61 0 3.09-.59 4.23-1.57l.27.28v.79l5 4.99L20.49 19l-4.99-5zm-6 0C7.01 14 5 11.99 5 9.5S7.01 5 9.5 5 14 7.01 14 9.5 11.99 14 9.5 14z"></path></svg>
        <input id="sb-q" type="text" placeholder="Keresés" autocomplete="off" spellcheck="false">
      </div>
    </div>
    <div class="sb-body">
      <button class="sb-new" id="btn-sb-new">
        <svg viewBox="0 0 24 24"><path d="M19 13H13V19H11V13H5V11H11V5H13V11H19V13Z"></path></svg>
        Új beszélgetés
      </button>
      <div class="sb-sec">Legutóbbi</div>
      <div id="hlist"></div>
    </div>
  </div>
  <div id="content">
    <div id="topbar">
      <div class="topbar-left">
        <button class="topbtn" id="btn-sidebar" aria-label="Beszélgetések">
          <svg viewBox="0 0 24 24"><path d="M3 18h18v-2H3v2zm0-5h18v-2H3v2zm0-7v2h18V6H3z"></path></svg>
        </button>
      </div>
      <div class="topbar-right">
        <div class="topchip" id="session-chip">Új beszélgetés</div>
      </div>
    </div>
    <div id="scroll-area">
      <div id="msg-list"></div>
    </div>
    <div id="ib-wrap">
      <div class="ib-inner">
        <div class="ib-row">
          <button class="ibtn" id="btn-new-chat" aria-label="Új beszélgetés">
            <svg viewBox="0 0 24 24"><path d="M19 13H13V19H11V13H5V11H11V5H13V11H19V13Z"></path></svg>
          </button>
          <div class="ibox">
            <textarea id="ta" rows="1" placeholder="Írj egy üzenetet"></textarea>
          </div>
          <button class="sbtn" id="sbtn" disabled aria-label="Küldés">
            <svg viewBox="0 0 24 24"><path d="M2.01 21 23 12 2.01 3 2 10l15 2-15 2z"></path></svg>
          </button>
        </div>
      </div>
    </div>
  </div>
  <button id="stb" aria-label="Ugrás az aljára">
    <svg viewBox="0 0 24 24"><path d="M7 10l5 5 5-5z"></path></svg>
  </button>
  <div id="toasts" aria-live="polite"></div>
</div>
<script>
(() => {
  const STORAGE_KEY = "bytez_chat_sessions_v1";
  const $ = id => document.getElementById(id);
  const sa = $("scroll-area");
  const ml = $("msg-list");
  const ta = $("ta");
  const sbtn = $("sbtn");
  const stb = $("stb");
  const hlist = $("hlist");
  const chip = $("session-chip");
  const searchInput = $("sb-q");

  let sessions = [];
  let currentSessionId = null;
  let sending = false;

  function uid() {
    return "s_" + Date.now().toString(36) + "_" + Math.random().toString(36).slice(2, 10);
  }

  function nowIso() {
    return new Date().toISOString();
  }

  function timeLabel(ts) {
    return new Date(ts).toLocaleTimeString([], { hour: "2-digit", minute: "2-digit" });
  }

  function saveSessions() {
    localStorage.setItem(STORAGE_KEY, JSON.stringify(sessions));
  }

  function loadSessions() {
    try {
      const parsed = JSON.parse(localStorage.getItem(STORAGE_KEY) || "[]");
      if (Array.isArray(parsed)) {
        sessions = parsed.filter(session => session && typeof session === "object" && typeof session.id === "string" && Array.isArray(session.messages));
      }
    } catch (_) {
      sessions = [];
    }
  }

  function currentSession() {
    return sessions.find(session => session.id === currentSessionId) || null;
  }

  function previewForMessages(messages) {
    for (const message of messages) {
      if (message.role === "user" && typeof message.content === "string" && message.content.trim()) {
        const firstLine = message.content.trim().split(/\n+/)[0].trim();
        return firstLine.length > 80 ? firstLine.slice(0, 80) + "…" : firstLine;
      }
    }
    return "Új beszélgetés";
  }

  function sortSessions() {
    sessions.sort((a, b) => new Date(b.updatedAt).getTime() - new Date(a.updatedAt).getTime());
  }

  function ensureSession() {
    let session = currentSession();
    if (session) return session;
    session = {
      id: uid(),
      title: "Új beszélgetés",
      createdAt: nowIso(),
      updatedAt: nowIso(),
      messages: []
    };
    sessions.unshift(session);
    currentSessionId = session.id;
    saveSessions();
    return session;
  }

  function createNewSession(focusComposer) {
    const session = {
      id: uid(),
      title: "Új beszélgetés",
      createdAt: nowIso(),
      updatedAt: nowIso(),
      messages: []
    };
    sessions.unshift(session);
    currentSessionId = session.id;
    saveSessions();
    renderHistory();
    renderMessages();
    if (focusComposer) ta.focus();
    closeSidebar();
  }

  function updateSessionFromMessages() {
    const session = ensureSession();
    session.updatedAt = nowIso();
    session.title = previewForMessages(session.messages);
    sortSessions();
    saveSessions();
    renderHistory();
    updateChip();
  }

  function escapeHtml(value) {
    return String(value)
      .replace(/&/g, "&amp;")
      .replace(/</g, "&lt;")
      .replace(/>/g, "&gt;")
      .replace(/"/g, "&quot;")
      .replace(/'/g, "&#39;");
  }

  function renderInlineMarkdown(text) {
    let html = escapeHtml(text);
    const code = [];
    html = html.replace(/`([^`\n]+)`/g, (_, part) => {
      const i = code.length;
      code.push(part);
      return "\u001e" + i + "\u001e";
    });
    html = html.replace(/\*\*\*(.+?)\*\*\*/g, "<strong><em>$1</em></strong>");
    html = html.replace(/\*\*(.+?)\*\*/g, "<strong>$1</strong>");
    html = html.replace(/__(.+?)__/g, "<strong>$1</strong>");
    html = html.replace(/\*([^*\n]+)\*/g, "<em>$1</em>");
    html = html.replace(/$begin:math:display$\(\[\^$end:math:display$]+)\]$begin:math:text$\(https\?\:\\\/\\\/\[\^\\s\)\]\+\)$end:math:text$/g, '$1');
    code.forEach((part, i) => {
      html = html.replace("\u001e" + i + "\u001e", '<span class="ic">' + part + '</span>');
    });
    return html;
  }

  function renderMarkdown(text) {
    const source = String(text || "").replace(/\r\n/g, "\n");
    if (!source.trim()) return "";
    const blocks = source.split(/\n\n+/);
    const rendered = [];
    for (const block of blocks) {
      if (/^```/.test(block.trim())) {
        const match = block.match(/^```([^\n]*)\n?([\s\S]*?)```$/);
        const lang = match ? match[1].trim() : "code";
        const code = match ? match[2] : block;
        rendered.push('<div class="cb"><div class="cb-hdr"><span class="cb-lang">' + escapeHtml(lang || "code") + '</span><button class="cb-copy" type="button">Másol</button></div><pre><code>' + escapeHtml(code.replace(/^\n+|\n+$/g, "")) + '</code></pre></div>');
        continue;
      }
      const lines = block.split("\n");
      if (lines.every(line => /^\s*[-*+]\s+/.test(line))) {
        rendered.push("<ul>" + lines.map(line => "<li>" + renderInlineMarkdown(line.replace(/^\s*[-*+]\s+/, "")) + "</li>").join("") + "</ul>");
        continue;
      }
      rendered.push("<p>" + lines.map(line => renderInlineMarkdown(line)).join("<br>") + "</p>");
    }
    return rendered.join("");
  }

  function attachCopyHandlers(root) {
    root.querySelectorAll(".cb-copy").forEach(button => {
      if (button.dataset.bound === "1") return;
      button.dataset.bound = "1";
      button.addEventListener("click", () => {
        const code = button.closest(".cb").querySelector("code");
        copyText(code.textContent || "", button, "Másol");
      });
    });
  }

  function copyText(value, button, label) {
    const reset = () => { if (button) button.textContent = label; };
    const done = ok => {
      if (button) button.textContent = ok ? "Másolva" : "Hiba";
      setTimeout(reset, 1600);
    };
    if (navigator.clipboard && navigator.clipboard.writeText) {
      navigator.clipboard.writeText(value).then(() => done(true)).catch(() => fallbackCopy(value, done));
    } else {
      fallbackCopy(value, done);
    }
  }

  function fallbackCopy(value, done) {
    const el = document.createElement("textarea");
    el.value = value;
    el.style.position = "fixed";
    el.style.opacity = "0";
    document.body.appendChild(el);
    el.select();
    let ok = false;
    try { ok = document.execCommand("copy"); } catch (_) {}
    document.body.removeChild(el);
    done(ok);
  }

  function messageCopyText(message) {
    return typeof message.content === "string" ? message.content : "";
  }

  function makeUserMessage(message) {
    const group = document.createElement("div");
    group.className = "msg-group u";
    const bubble = document.createElement("div");
    bubble.className = "bubble";
    bubble.textContent = message.content;
    group.appendChild(bubble);
    const actions = document.createElement("div");
    actions.className = "t-row";
    const copy = document.createElement("button");
    copy.className = "tact";
    copy.type = "button";
    copy.textContent = "Másol";
    copy.addEventListener("click", event => copyText(messageCopyText(message), event.currentTarget, "Másol"));
    actions.appendChild(copy);
    group.appendChild(actions);
    const time = document.createElement("div");
    time.className = "btime";
    time.style.textAlign = "right";
    time.textContent = timeLabel(message.ts || nowIso());
    group.appendChild(time);
    return group;
  }

  function makeAssistantMessage(message) {
    const group = document.createElement("div");
    group.className = "msg-group a";
    const bubble = document.createElement("div");
    bubble.className = "ai-bubble";
    const md = document.createElement("div");
    md.className = "md";
    md.innerHTML = renderMarkdown(message.content || "");
    bubble.appendChild(md);
    group.appendChild(bubble);
    const actions = document.createElement("div");
    actions.className = "t-row";
    const copy = document.createElement("button");
    copy.className = "tact";
    copy.type = "button";
    copy.textContent = "Másol";
    copy.addEventListener("click", event => copyText(messageCopyText(message), event.currentTarget, "Másol"));
    actions.appendChild(copy);
    group.appendChild(actions);
    const time = document.createElement("div");
    time.className = "btime";
    time.textContent = timeLabel(message.ts || nowIso());
    group.appendChild(time);
    attachCopyHandlers(group);
    return group;
  }

  function makeErrorMessage(text) {
    const group = document.createElement("div");
    group.className = "msg-group e";
    const bubble = document.createElement("div");
    bubble.className = "err-bbl";
    bubble.textContent = text;
    group.appendChild(bubble);
    return group;
  }

  function makeTyping() {
    const group = document.createElement("div");
    group.className = "msg-group a";
    group.id = "typing";
    const typing = document.createElement("div");
    typing.className = "typing";
    for (let i = 0; i < 3; i += 1) {
      const dot = document.createElement("div");
      dot.className = "td";
      typing.appendChild(dot);
    }
    group.appendChild(typing);
    return group;
  }

  function removeTyping() {
    const typing = $("typing");
    if (typing) typing.remove();
  }

  function renderMessages() {
    ml.innerHTML = "";
    const session = ensureSession();
    if (!session.messages.length) {
      const empty = document.createElement("div");
      empty.className = "h-empty";
      empty.style.minHeight = "58vh";
      empty.innerHTML = '<svg viewBox="0 0 24 24"><path d="M20 2H4c-1.1 0-2 .9-2 2v18l4-4h14c1.1 0 2-.9 2-2V4c0-1.1-.9-2-2-2z"></path></svg><p>Kezdj új beszélgetést a Bytez és Claude Opus 4.6 modellel.</p>';
      ml.appendChild(empty);
      updateChip();
      goBottom(false);
      return;
    }
    for (const message of session.messages) {
      if (message.role === "user") ml.appendChild(makeUserMessage(message));
      else if (message.role === "assistant") ml.appendChild(makeAssistantMessage(message));
    }
    updateChip();
    goBottom(false);
  }

  function renderHistory() {
    sortSessions();
    const query = searchInput.value.trim().toLowerCase();
    const visible = sessions.filter(session => !query || session.title.toLowerCase().includes(query) || session.messages.some(message => String(message.content || "").toLowerCase().includes(query)));
    hlist.innerHTML = "";
    if (!visible.length) {
      const empty = document.createElement("div");
      empty.className = "h-empty";
      empty.innerHTML = '<svg viewBox="0 0 24 24"><path d="M20 2H4c-1.1 0-2 .9-2 2v18l4-4h14c1.1 0 2-.9 2-2V4c0-1.1-.9-2-2-2z"></path></svg><p>' + (query ? "Nincs találat" : "Még nincs beszélgetés") + '</p>';
      hlist.appendChild(empty);
      return;
    }
    for (const session of visible) {
      const card = document.createElement("div");
      card.className = "hcard" + (session.id === currentSessionId ? " active" : "");
      const body = document.createElement("div");
      body.className = "hcard-body";
      const pre = document.createElement("div");
      pre.className = "hcard-pre";
      pre.textContent = session.title || "Új beszélgetés";
      const meta = document.createElement("div");
      meta.className = "hcard-meta";
      meta.textContent = new Date(session.updatedAt).toLocaleString([], { month: "short", day: "numeric", hour: "2-digit", minute: "2-digit" });
      body.appendChild(pre);
      body.appendChild(meta);
      const del = document.createElement("button");
      del.className = "hcard-del";
      del.type = "button";
      del.setAttribute("aria-label", "Törlés");
      del.innerHTML = '<svg viewBox="0 0 24 24"><path d="M16 9v10H8V9h8m-1.5-6h-5l-1 1H5v2h14V4h-3.5l-1-1z"></path></svg>';
      del.addEventListener("click", event => {
        event.stopPropagation();
        deleteSession(session.id);
      });
      card.appendChild(body);
      card.appendChild(del);
      card.addEventListener("click", () => {
        currentSessionId = session.id;
        renderHistory();
        renderMessages();
        closeSidebar();
      });
      hlist.appendChild(card);
    }
  }

  function updateChip() {
    const session = ensureSession();
    chip.textContent = session.title || "Új beszélgetés";
  }

  function deleteSession(id) {
    const index = sessions.findIndex(session => session.id === id);
    if (index === -1) return;
    const isCurrent = sessions[index].id === currentSessionId;
    sessions.splice(index, 1);
    if (!sessions.length) {
      currentSessionId = null;
      createNewSession(false);
      toast("Beszélgetés törölve", "ok");
      return;
    }
    if (isCurrent) currentSessionId = sessions[0].id;
    saveSessions();
    renderHistory();
    renderMessages();
    toast("Beszélgetés törölve", "ok");
  }

  function openSidebar() {
    $("sidebar").classList.add("open");
  }

  function closeSidebar() {
    $("sidebar").classList.remove("open");
  }

  function toast(message, type, ms) {
    const icons = {
      err: '<svg viewBox="0 0 24 24"><path d="M12 2C6.48 2 2 6.48 2 12s4.48 10 10 10 10-4.48 10-10S17.52 2 12 2zm1 15h-2v-2h2v2zm0-4h-2V7h2v6z"></path></svg>',
      ok: '<svg viewBox="0 0 24 24"><path d="M9 16.17 4.83 12l-1.42 1.41L9 19 21 7l-1.41-1.41z"></path></svg>',
      inf: '<svg viewBox="0 0 24 24"><path d="M12 2C6.48 2 2 6.48 2 12s4.48 10 10 10 10-4.48 10-10S17.52 2 12 2zm1 15h-2v-6h2v6zm0-8h-2V7h2v2z"></path></svg>'
    };
    const el = document.createElement("div");
    el.className = "toast " + type;
    el.innerHTML = (icons[type] || icons.inf) + "<span>" + escapeHtml(message) + "</span>";
    $("toasts").appendChild(el);
    const dismiss = () => {
      el.classList.add("out");
      setTimeout(() => el.remove(), 220);
    };
    el.addEventListener("click", dismiss);
    setTimeout(dismiss, ms || 3000);
  }

  function nearBottom(distance) {
    return sa.scrollHeight - sa.scrollTop - sa.clientHeight < (distance || 140);
  }

  function goBottom(smooth) {
    sa.scrollTo({ top: sa.scrollHeight, behavior: smooth ? "smooth" : "auto" });
  }

  function updateScrollButton() {
    stb.classList.toggle("show", !nearBottom(200));
  }

  function autosize() {
    ta.style.height = "auto";
    ta.style.height = Math.min(ta.scrollHeight, 104) + "px";
    sbtn.disabled = !ta.value.trim() || sending;
  }

  function normalizeAssistantText(value) {
    if (typeof value === "string") return value;
    if (Array.isArray(value)) {
      return value.map(normalizeAssistantText).filter(Boolean).join("\n\n");
    }
    if (value && typeof value === "object") {
      if (Array.isArray(value.choices) && value.choices.length) {
        const parts = value.choices.map(choice => {
          if (choice && choice.message && typeof choice.message.content === "string") return choice.message.content;
          if (choice && typeof choice.text === "string") return choice.text;
          return normalizeAssistantText(choice);
        }).filter(Boolean);
        if (parts.length) return parts.join("\n\n");
      }
      if (Array.isArray(value.content)) {
        const parts = value.content.map(item => {
          if (typeof item === "string") return item;
          if (item && typeof item === "object") {
            if (typeof item.text === "string") return item.text;
            if (typeof item.content === "string") return item.content;
          }
          return "";
        }).filter(Boolean);
        if (parts.length) return parts.join("\n\n");
      }
      if (typeof value.text === "string") return value.text;
      if (typeof value.content === "string") return value.content;
      if (typeof value.output_text === "string") return value.output_text;
      return JSON.stringify(value, null, 2);
    }
    if (value == null) return "";
    return String(value);
  }

  async function sendMessage() {
    const text = ta.value.trim();
    if (!text || sending) return;
    const session = ensureSession();
    const userMessage = { role: "user", content: text, ts: nowIso() };
    session.messages.push(userMessage);
    updateSessionFromMessages();
    renderMessages();
    ta.value = "";
    autosize();
    sending = true;
    sbtn.disabled = false;
    ml.appendChild(makeTyping());
    goBottom(true);

    try {
      const response = await fetch("/api/chat", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ messages: session.messages.map(message => ({ role: message.role, content: message.content })) })
      });
      const raw = await response.text();
      let data = null;
      try {
        data = raw ? JSON.parse(raw) : null;
      } catch {
        data = null;
      }
      removeTyping();
      if (!response.ok) throw new Error(data && data.error ? data.error : raw || "A kérés sikertelen volt");
      const assistantText = normalizeAssistantText(data ? (data.output ?? data) : raw).trim();
      if (!assistantText) throw new Error("A modell üres választ adott");
      const assistantMessage = { role: "assistant", content: assistantText, ts: nowIso() };
      session.messages.push(assistantMessage);
      updateSessionFromMessages();
      renderMessages();
      goBottom(true);
    } catch (error) {
      removeTyping();
      const message = error && error.message ? error.message : "Ismeretlen hiba";
      ml.appendChild(makeErrorMessage(message));
      goBottom(true);
      toast(message, "err", 4200);
    } finally {
      sending = false;
      autosize();
      ta.focus();
    }
  }

  $("btn-sidebar").addEventListener("click", openSidebar);
  $("btn-sb-close").addEventListener("click", closeSidebar);
  $("btn-new-chat").addEventListener("click", () => createNewSession(true));
  $("btn-sb-new").addEventListener("click", () => createNewSession(true));
  $("btn-sb-clear-search").addEventListener("click", () => {
    searchInput.value = "";
    renderHistory();
    searchInput.focus();
  });
  s

